import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const root = new Group();

  // Apply initial transform (scenePosition is applied by adapter, but we set base)
  root.position.set(-2.5, 1.6, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // Store cleanup callbacks from primitives
  const primitiveCleanups = [];

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const result = ctx.primitives[prim.name](root, prim.params);
      if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    }
  }

  // Hover animation (rise‑in) and click emit
  const originalY = root.position.y;
  let hoverTimeline = null;

  root.userData.handlers = {
    hover: (enter) => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();
      if (enter) {
        hoverTimeline.to(root.position, {
          y: originalY + 0.15,
          duration: 0.7,
          ease: 'power3.out',
        });
      } else {
        hoverTimeline.to(root.position, {
          y: originalY,
          duration: 0.7,
          ease: 'power3.out',
        });
      }
    },
    click: () => {
      ctx.emit('hub-home.select', {});
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    primitiveCleanups.forEach((fn) => fn());

    // Dispose meshes added from GLB
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  // Load GLB mesh if provided
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
    }).catch((e) => {
      console.error('Failed to load GLB:', e);
    });
  }

  // No text content for this tile
  return root;
}
